unsigned char data = 0b10101010;
int bit_position = 4; // Target 5th bit (0-indexed)

// 1. Create the toggle mask
const unsigned char MASK = (1 << bit_position);

// 2. Toggle operation (data = data ^ MASK)
data ^= MASK;       // data is now 0b10111010

// 3. Toggling again flips it back
data ^= MASK;       // data is now 0b10101010
